/* eslint-disable max-len */
import { Component, OnInit } from '@angular/core';
import { FormGroup, FormBuilder, Validators } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { ToastController, LoadingController, AlertController } from '@ionic/angular';
import { GResponse } from '../../../../../core/common/GResponse';
import { SharedIonic } from '../../../../../core/common/SharedIonic';
import { ISliderModel, SliderModel } from '../../../../../data/model/site/SliderModel';
import { SliderService } from '../../../../../data/service/site/Slider.service';
import { Title } from '@angular/platform-browser';

@Component({
  selector: 'app-product-sliders',
  templateUrl: './product-sliders.component.html',
  styleUrls: ['./product-sliders.component.scss'],
})
export class ProductSlidersPage implements OnInit {

  selectedId = 0;
  sliders: ISliderModel[] = [];
  isSelected = false;
  selectedCategory = 'add';
  form: FormGroup;

  constructor(
    private fb: FormBuilder,
    private sliderService: SliderService,
    public toastController: ToastController,
    public loadingController: LoadingController,
    private router: Router,
    public alertController: AlertController
  ) { }

  ngOnInit(): void {

    this.form = this.fb.group({
      description: ['', [Validators.required, Validators.minLength(1), Validators.maxLength(2000)]],
      link: ['', [Validators.maxLength(1000)]],
      imageName: ['', []],
      imageNamePhone: ['', []],
      title: ['', [Validators.required, Validators.minLength(1), Validators.maxLength(100)]],
      isCourse: [false, [Validators.required]],
      isProduct: [false, [Validators.required]]
    });

    SharedIonic.loading(this.loadingController);

    this.sliderService.GetAllAdminSliders().subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (res.status === GResponse.SuccessStatus) {
          this.sliders = res.data;
        } else {
          SharedIonic.toast(this.toastController, 'موردی یافت نشد');
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }

  onSelected(index: string | number) {

    const model = this.sliders[index];
    this.selectedId = model.id;

    this.form.setValue({
      title: model.title,
      description: model.description,
      link: model.link,
      isCourse: model.isCourse,
      isProduct: model.isProduct,
      imageName: model.imageName,
      imageNamePhone: model.imageNamePhone
    });

    this.isSelected = true;
  }

  async presentAlertConfirm3() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن به درج هستید؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'بله',
          handler: () => {
            this.onAddTags();
          }
        }
      ]
    });

    await alert.present();
  }

  async presentAlertConfirm2() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن به آپدیت هستید؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'بله',
          handler: () => {
            this.onUpdateTags();
          }
        }
      ]
    });

    await alert.present();
  }

  onRemoveEditTag(index: string | number) {

    const model = this.sliders[+index];

    SharedIonic.loading(this.loadingController);

    this.sliderService.RemoveSlide(model.id).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (res.status === GResponse.SuccessStatus) {
          this.sliders[+index].isDelete = true;
          SharedIonic.successToast(this.toastController);
        } else {
          SharedIonic.unSuccessToast(this.toastController);
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }

  onActive(index: string | number) {

    const model = this.sliders[+index];

    SharedIonic.loading(this.loadingController);

    this.sliderService.ActiveSlide(model.id).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (res.status === GResponse.SuccessStatus) {
          this.sliders[+index].isDelete = false;
          SharedIonic.successToast(this.toastController);
        } else {
          SharedIonic.unSuccessToast(this.toastController);
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }

  onCancel() {
    this.isSelected = false;
  }

  onUpdateTags() {

    if (!this.form.valid) {
      return;
    }

    SharedIonic.loading(this.loadingController);

    this.sliderService.AddOrUpdateSlider(
      new SliderModel(this.selectedId, this.form.value.title,this.form.value.imageName,this.form.value.imageNamePhone,this.form.value.link,this.form.value.description,this.form.value.isCourse,this.form.value.isProduct)
    ).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (res.status === GResponse.SuccessStatus) {
          const index = this.sliders.findIndex(e => e.id === this.selectedId);
          this.sliders[index].description = this.form.value.description;
          this.sliders[index].title = this.form.value.title;
          this.sliders[index].link = this.form.value.link;
          this.sliders[index].isCourse = this.form.value.isCourse;
          this.sliders[index].isProduct = this.form.value.isProduct;
          this.sliders[index].imageName = this.form.value.imageName;
          this.sliders[index].imageNamePhone = this.form.value.imageNamePhone;

          SharedIonic.successToast(this.toastController);
        } else {
          SharedIonic.unSuccessToast(this.toastController);
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }

  onAddTags() {

    if (!this.form.valid) {
      return;
    }

    SharedIonic.loading(this.loadingController);

    const model = new SliderModel(0, this.form.value.title,this.form.value.imageName,this.form.value.imageNamePhone,this.form.value.link,this.form.value.description,this.form.value.isCourse,this.form.value.isProduct);

    this.sliderService.AddOrUpdateSlider(
      model
    ).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (res.status === GResponse.SuccessStatus) {
          model.id = res.data;
          this.sliders.push(model);

          SharedIonic.successToast(this.toastController);
        } else {
          SharedIonic.unSuccessToast(this.toastController);
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }

  async presentRemoveAlertConfirm(index: number | string) {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن به حذف هستید؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'حذف',
          handler: () => {
            this.onRemoveEditTag(index);
          }
        }
      ]
    });

    await alert.present();
  }

  async presentRemoveAlertConfirm2(index: number | string) {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن به فعال سازی هستید؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'فعال',
          handler: () => {
            this.onActive(index);
          }
        }
      ]
    });

    await alert.present();
  }

  onSelectItem(id: string | number) {

    this.selectedId = +id;

    this.form.setValue({
      title: this.sliders.find(e => e.id === id).title,
      description: this.sliders.find(e => e.id === id).description,
      link: this.sliders.find(e => e.id === id).link,
      isCourse: this.sliders.find(e => e.id === id).isCourse,
      isProduct: this.sliders.find(e => e.id === id).isProduct,
      imageName: this.sliders.find(e => e.id === id).imageName,
      imageNamePhone: this.sliders.find(e => e.id === id).imageNamePhone,
    });

    this.isSelected = true;
  }
}
